cat > /app/boot.exp << 'EOF'
#!/usr/bin/expect -f
set timeout 240
spawn qemu-system-x86_64 -m 512 -cdrom /app/alpine.iso -drive file=/app/alpine-disk.qcow2,if=virtio,format=qcow2 -nic user,hostfwd=tcp:127.0.0.1:2222-10.0.2.15:22 -nographic
expect -re {boot:}
send "\r"
expect -re {~#}
send "echo password123 | passwd root \r"
expect -re {~#}
send "rc-service sshd start \r"
expect -re {~#}
send "ssh-keyscan -H 127.0.0.1 2>/dev/null >> /root/.ssh/known_hosts 2>/dev/null; true\r"
expect -re {~#}
send "sleep 6000\r"
expect eof
EOF
chmod +x /app/boot.exp

expect << 'EOF'
set timeout 30
spawn ssh -p 2222 -o UserKnownHostsFile=/root/.ssh/known_hosts root@127.0.0.1
expect {
  "assword:" { send "password123\r"; exp_continue }
  "Are you sure" { send "yes\r"; exp_continue }
  "#" {}
  timeout { puts "TIMEOUT"; exit 1 }
  eof { puts "EOF"; exit 1 }
}
send "echo GUEST_OK\r"
expect "GUEST_OK"
expect "#"
send "exit\r"
expect eof
EOF

